<?php
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/view_helpers.php';require_login();$admin=current_user()['role']==='admin';$sql='SELECT r.report_id,r.report_title,r.created_at,s.project_id,s.scanned_at,p.name project_name,u.full_name owner FROM reports r JOIN scans s ON s.scan_id=r.scan_id JOIN projects p ON p.project_id=s.project_id JOIN users u ON u.user_id=p.user_id';$args=[];if(!$admin){$sql.=' WHERE p.user_id=?';$args[]=(int)current_user()['user_id'];}$sql.=' ORDER BY r.created_at DESC';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();page_header('Security Reports');?>
<div class="page-heading"><div><span class="eyebrow">ASSESSMENT DOCUMENTATION</span><h1>Security Reports</h1><p><?=$admin?'Read-only consolidated reports generated by Developers.':'Consolidated reports for your completed scan runs.'?></p></div></div>
<div class="card"><div class="card-header"><strong>Consolidated assessment reports</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Report</th><th>Project</th><?php if($admin):?><th>Owner</th><?php endif;?><th>Scan date</th><th>Generated</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$c=compliance_for_scan($pdo,(int)$r['project_id'],['scanned_at'=>$r['scanned_at']]);?><tr><td><?=e($r['report_title'])?></td><td><?=e($r['project_name'])?><div class="small"><?=compliance_badge($c['status'])?></div></td><?php if($admin):?><td><?=e($r['owner'])?></td><?php endif;?><td><?=e($r['scanned_at'])?></td><td><?=e($r['created_at'])?></td><td><a class="btn btn-sm btn-outline-primary" href="<?=e(url('report.php?id='.$r['report_id']))?>">Open</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?=$admin?6:5?>" class="empty-state">No reports have been generated. Developers can generate a report from a completed scan.</td></tr><?php endif;?></tbody></table></div></div>
<?php require APP_ROOT.'/includes/footer.php';?>
